import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../../../Core/Resources/app_colors.dart';import '../../../../../../Core/Resources/app_fonts.dart';import '../../../../../../Core/Resources/app_icons.dart';import '../../../../../../Core/Utils/Widget/Images/build_image.dart';import '../../../../App/Home/presentation/manager/home_cubit.dart';class BuildUserDataAppBar extends StatelessWidget {  const BuildUserDataAppBar({    super.key,  });  @override  Widget build(BuildContext context) {    return SliverToBoxAdapter(      child: ListTile(        contentPadding: EdgeInsets.only(top: 35).w,        minVerticalPadding: 0,        style: ListTileStyle.drawer,        title: Text(          context.watch<HomeCubit>().state.userDataModel!.name,          style: AppTextStyles.h6Bold,        ),        subtitle: Text(          "${context.watch<HomeCubit>().state.userDataModel!.email.split("@").first}@",          style: AppTextStyles.bodyMediumMedium.copyWith(            color: AppColors.grayscale80,          ),        ),        minLeadingWidth: 50.w,        leading: CircleAvatar(            radius: 30.r,            child: BuildImageAssets(              url: context.read<HomeCubit>().state.userDataModel?.photo,              setDefaultImage: true,              width: 60.w,              height: 60.h,            )),        trailing: AppIcons.edit,      ),    );  }}